mapper.select:
SELECT  FROM ddc_env WHERE tenant_id = #{tenantId} AND deleted_at IS NULL
AND id IN #{id}
ORDER BY sort_order, env_code, id

mapper.update:
UPDATE ddc_env SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime}
WHERE tenant_id = #{et.tenantId} AND id = #{et.id} AND version = #{et.version} AND deleted_at IS NULL
